export const getWakeComputerUrl = (organizationId: string, botId: string) => {
  return `/api/v2/organizations/${encodeURIComponent(String(organizationId))}/computers/${encodeURIComponent(String(botId))}/wake`;
};

/**
 * Start the Bot's computer when it is off, because a person opened its screen or terminal, and answer at once with its state without waiting for it to come up. The audit trail records a computer resumed this way.
 * @summary Start a Bot's computer
 */
export const wakeComputer = async (
  organizationId: string,
  botId: string,
  headers: WakeComputerHeaders,
  options?: Parameters<typeof apiRequest>[1],
): Promise<ComputerStatus> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return apiRequest<ComputerStatus>(getWakeComputerUrl(organizationId, botId), {
    ...options,
    method: "POST",
    headers: { ...headers, ...getHeaders(options?.headers) },
  });
};

